import {
    _decorator, Component, Node, Vec3, Color, Camera, find, director,
    input, Input, EventKeyboard, KeyCode,
} from 'cc';
import { buildWorld } from './world/WorldBuilder';
import { buildHumanoid } from './core/CharacterBuilder';
import { createPrimitiveNode, Palette, clearMaterialCache } from './core/PrimitiveFactory';
import { PlayerStats } from './player/PlayerStats';
import { PlayerController } from './player/PlayerController';
import { PlayerCombat } from './player/PlayerCombat';
import { Inventory } from './inventory/Inventory';
import { EnemySpawner } from './enemies/EnemySpawner';
import { NPC, NPCDefs, buildNpcNode } from './npc/NPC';
import { QuestManager } from './quest/QuestManager';
import { UIManager } from './ui/UIManager';
import { CameraFollow } from './world/CameraFollow';
import { EventBus, GameEvents } from './core/EventBus';

const { ccclass } = _decorator;

@ccclass('GameBootstrap')
export class GameBootstrap extends Component {

    start() {
        // Clear stale material cache from any previous editor Play session.
        // Module-level Maps survive editor stop/play cycles; destroyed Materials
        // inside them cause "Cannot read properties of undefined (reading 'localSetLayout')".
        clearMaterialCache();

        const scene = this.node.scene!;

        // 1) Use the pre-baked world that lives inside the scene file.
        //    (See WorldBuilderBaker for how to bake it in the editor.)
        //    Fallback: if no baked world is found, generate one procedurally so
        //    the project still runs out-of-the-box.
        let world = this.findInScene(scene, 'World');
        if (!world) {
            console.warn('[GameBootstrap] No baked "World" node found in scene. ' +
                'Falling back to runtime generation. ' +
                'Add a WorldBuilderBaker component in the editor and click "Bake Now" to pre-build the environment.');
            world = buildWorld();
            scene.addChild(world);
        } else {
            console.log('[GameBootstrap] Using pre-baked World from scene.');
        }

        // 2) Build the player
        const playerParts = buildHumanoid('Player', {
            skin: Palette.skin,
            shirt: new Color(70, 100, 160),    // blue tunic
            pants: new Color(60, 50, 40),
            hair: new Color(80, 55, 35),
        }, 1);
        playerParts.root.setPosition(0, 0, -2);
        scene.addChild(playerParts.root);

        // Default weapon on player
        const sword = createPrimitiveNode('Weapon', 'box', new Vec3(0.14, 1.1, 0.14), Palette.iron);
        sword.setPosition(0, -0.55, 0);
        playerParts.weaponSlot.addChild(sword);

        // Player components
        const stats = playerParts.root.addComponent(PlayerStats);
        const inventory = playerParts.root.addComponent(Inventory);
        inventory.stats = stats;
        const controller = playerParts.root.addComponent(PlayerController);
        controller.stats = stats;
        controller.legs = { l: playerParts.leftLeg, r: playerParts.rightLeg };
        controller.arms = { l: playerParts.leftArm, r: playerParts.rightArm };
        controller.body = playerParts.body;
        const combat = playerParts.root.addComponent(PlayerCombat);
        combat.stats = stats;

        // Starting inventory
        inventory.addItem('rusty_sword', 1);
        inventory.addItem('cloth_hood', 1);
        inventory.addItem('leather_vest', 1);
        inventory.addItem('leather_boots', 1);
        inventory.addItem('health_potion', 5);
        inventory.addItem('mana_potion', 3);
        inventory.equip('rusty_sword');
        inventory.equip('leather_vest');
        inventory.equip('cloth_hood');
        inventory.equip('leather_boots');

        // 3) Camera follow
        let camNode = scene.getChildByName('Main Camera');
        if (!camNode) {
            camNode = new Node('Main Camera');
            camNode.addComponent(Camera);
            scene.addChild(camNode);
        }
        const cam = camNode.getComponent(Camera) ?? camNode.addComponent(Camera);
        cam.clearColor = { x: 0.45, y: 0.55, z: 0.75, w: 1 } as any;
        cam.fov = 55;
        cam.far = 500;

        let camFollow = camNode.getComponent(CameraFollow);
        if (!camFollow) camFollow = camNode.addComponent(CameraFollow);
        camFollow.target = playerParts.root;
        camFollow.distance = 11;
        camFollow.height = 5;
        camFollow.pitch = 28;
        controller.cameraNode = camNode;

        // 4) Spawn NPCs
        const npcsParent = new Node('NPCs');
        world.addChild(npcsParent);
        for (const def of NPCDefs) {
            const built = buildNpcNode(def);
            npcsParent.addChild(built.root);
            const comp = built.root.addComponent(NPC);
            comp.init(def, playerParts.root);
            comp.marker = built.marker;
        }

        // Emit NPC range hint to UI
        this.schedule(() => {
            let anyClose = false;
            const pp = playerParts.root.worldPosition;
            for (const c of npcsParent.children) {
                const a = c.worldPosition;
                const d = Math.hypot(a.x - pp.x, a.z - pp.z);
                if (d <= 3) { anyClose = true; break; }
            }
            EventBus.emit('npc_in_range', anyClose);
        }, 0.2);

        // 5) Quest manager
        const questNode = new Node('QuestManager');
        scene.addChild(questNode);
        const questMgr = questNode.addComponent(QuestManager);
        questMgr.inventory = inventory;
        questMgr.stats = stats;

        // 6) Enemy spawner
        const enemiesParent = new Node('Enemies');
        world.addChild(enemiesParent);
        const spawnerNode = new Node('EnemySpawner');
        scene.addChild(spawnerNode);
        const spawner = spawnerNode.addComponent(EnemySpawner);
        spawner.worldRoot = enemiesParent;
        spawner.player = playerParts.root;
        spawner.playerStats = stats;
        spawner.inventory = inventory;
        spawner.spawnAll();
        combat.enemies = spawner.enemies;

        // 7) UI Manager
        const uiNode = new Node('UI');
        scene.addChild(uiNode);
        const ui = uiNode.addComponent(UIManager);
        ui.stats = stats;
        ui.inventory = inventory;
        ui.combat = combat;
        ui.quests = questMgr;

        // 8) Global key shortcuts (I = inventory, L = quest log, ESC closes panels)
        input.on(Input.EventType.KEY_DOWN, (e: EventKeyboard) => {
            if (e.keyCode === KeyCode.KEY_I) EventBus.emit(GameEvents.UI_TOGGLE_INVENTORY);
            else if (e.keyCode === KeyCode.KEY_L) EventBus.emit(GameEvents.UI_TOGGLE_QUEST);
            else if (e.keyCode === KeyCode.ESCAPE) {
                EventBus.emit(GameEvents.DIALOG_CLOSE);
            }
        });

        // 9) Initial state push
        EventBus.emit(GameEvents.PLAYER_STATS_CHANGED, stats);
        EventBus.emit(GameEvents.INVENTORY_CHANGED, inventory);

        console.log('[GameBootstrap] Medieval RPG initialized!');
        console.log('  Player at:', playerParts.root.position);
        console.log('  NPCs:', NPCDefs.length, '  Enemies spawned:', spawner.enemies.length);
    }

    /** Recursively search the scene graph for a node by name. */
    private findInScene(root: Node, name: string): Node | null {
        if (root.name === name) return root;
        for (const child of root.children) {
            const hit = this.findInScene(child, name);
            if (hit) return hit;
        }
        return null;
    }
}
